mapper.select:
SELECT
    ${columnName} AS label,
    COUNT(*) AS value
FROM ${tableName}
WHERE tenant_id = #{tenantId}
  AND del_flag = 0
GROUP BY ${columnName}
ORDER BY value DESC

SELECT
    DATE(create_time) AS label,
    COUNT(*) AS value
FROM ${tableName}
WHERE tenant_id = #{tenantId}
  AND del_flag = 0
  AND create_time >= #{since}
GROUP BY DATE(create_time)
ORDER BY label ASC

SELECT COALESCE(SUM(${columnName}), 0)
FROM ${tableName}
WHERE tenant_id = #{tenantId}
  AND del_flag = 0
